/* symlink(2) - Create a symbolic link */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define TARGET_FILE "data_source.txt"
#define LINK_PATH   "data_link.sym"

int main() {
    // --- Setup: Create the target file ---
    FILE *fp = fopen(TARGET_FILE, "w");
    if (fp == NULL) {
        perror("Error creating target file");
        return EXIT_FAILURE;
    }
    fprintf(fp, "Hello, Symbolic Link World!\n");
    fclose(fp);
    printf("Target file created: %s\n", TARGET_FILE);

    // --- Create the symbolic link ---
    // The link will point from LINK_PATH to TARGET_FILE
    if (symlink(TARGET_FILE, LINK_PATH) == -1) {
        if (errno == EEXIST) {
            fprintf(stderr, "Warning: Link %s already exists. Deleting old link.\n", LINK_PATH);
            unlink(LINK_PATH);
            // Retry after deleting the conflicting path
            if (symlink(TARGET_FILE, LINK_PATH) == -1) {
                perror("symlink failed on retry");
                // Clean up the target file before exiting on failure
                unlink(TARGET_FILE);
                return EXIT_FAILURE;
            }
        } else {
            perror("symlink failed");
            unlink(TARGET_FILE);
            return EXIT_FAILURE;
        }
    }

    printf("Symbolic link successfully created: %s -> %s\n", LINK_PATH, TARGET_FILE);

    // --- Cleanup ---
    unlink(TARGET_FILE);
    unlink(LINK_PATH);
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}
